2.query:
timeseries requests = sum(observai.inference.requests), filter: { in(task, array($Task)) }
| fieldsAdd bucket_total = arraySum(requests)
| summarize total_requests = sum(bucket_total)

3.query:
timeseries requests = sum(observai.inference.requests), 
by: { outcome }, filter: { in(task, array($Task)) }
| fieldsAdd bucket_total = arraySum(requests)
| summarize { ok = sum(if(outcome == "ok", bucket_total, else: 0)), all = sum(bucket_total) }
| fieldsAdd success_rate_pct = if(all > 0, ok * 100.0 / all, else: 0.0)
| fields success_rate_pct

4.query:
timeseries latency = avg(observai.inference.latency), filter: { in(task, array($Task)) }
| fieldsAdd avg_latency_ms = arrayAvg(latency)
| fields avg_latency_ms

5.query:
timeseries { tin = sum(observai.tokens.in), tout = sum(observai.tokens.out) }, filter: { in(task, array($Task)) }
| fieldsAdd total_tokens = arraySum(tin) + arraySum(tout)
| fields total_tokens

10.query:
timeseries requests = sum(observai.inference.requests), 
by: { task }, filter: { in(task, array($Task)) }
| fieldsAdd bucket_total = arraySum(requests)
| summarize reqs = sum(bucket_total), by: { task }, total=sum(bucket_total)
| fieldsAdd pc=100*reqs/total
| sort pc desc

