17.query:
fetch spans
| filter span.name == "gateway.handle_prompt"
| filter in(ai.task, array($Task))
| filter ai.oversight.flagged == true
| filter isNotNull(ai.oversight.reasons)
| fieldsAdd reason = splitString(ai.oversight.reasons, "; ")
| expand reason
| fieldsAdd reason_category = if(contains(reason, "below floor"), "Confidence below floor",
                            else: if(contains(reason, "empty model output"), "Empty model output",
                            else: if(contains(reason, "requested review"), "Inference requested review",
                            else: "Other")))
| summarize occurrences = count(), by: { reason_category }
| sort occurrences desc
